-- Daily challenges for 2026-10-14: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-14. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('leaving-work-at-work', 'Leaving Work at Work', 'For anyone whose job follows them home in their head, their inbox or their evenings. Each day is one small step that closes the workday on purpose, so your evenings and weekends feel like your own again.', 'Work', 365, array['Work', 'Boundaries', 'Burnout']::text[], 1, '2026-10-14T17:00:00+00:00'::timestamptz),
  ('reading-for-pleasure', 'Reading for Pleasure', 'For anyone who used to love books but lost the habit somewhere along the way. Each day is one small step back toward reading for fun, from a single page at breakfast to a library visit, with no reading list to finish.', 'Wellbeing', 365, array['Self-Care', 'Mindfulness']::text[], 1, '2026-10-14T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('leaving-work-at-work', 'reading-for-pleasure');

